def _pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise ValueError("duplicate JSON member")
        result[key] = value
    return result

def decode(raw):
    return json.loads(raw.decode("utf-8"), object_pairs_hook=_pairs)

def digest(raw):
    return "sha256:" + hashlib.sha256(raw).hexdigest()

def canonical_path(value):
    if not isinstance(value, str) or not value or "\0" in value:
        raise ValueError("absolute public path required")
    path = Path(value)
    if not path.is_absolute() or str(path.resolve()).casefold() != str(path).casefold():
        raise ValueError("canonical public path required")
    return path

def public_ref(path):
    path = canonical_path(str(path))
    raw = path.read_bytes()
    return {"path": str(path), "sha256": digest(raw), "bytes": len(raw)}

def path_key(value):
    return str(canonical_path(value)).casefold()

def require_ref(value):
    if not isinstance(value, dict) or set(value) != {"path", "sha256", "bytes"}:
        raise ValueError("exact public reference shape required")
    if isinstance(value["bytes"], bool) or not isinstance(value["bytes"], int) or value["bytes"] < 0:
        raise ValueError("public reference length")
    path = canonical_path(value["path"])
    actual = public_ref(path)
    if (path_key(actual["path"]) != path_key(value["path"]) or
        actual["sha256"] != value["sha256"] or actual["bytes"] != value["bytes"]):
        raise ValueError("public reference changed")
    return path

def from_raw_pin(value):
    if not isinstance(value, dict) or set(value) != {"role", "path", "sha256", "bytes"}:
        raise ValueError("public RawPin shape required")
    return {key: value[key] for key in ("path", "sha256", "bytes")}

def read_ref(value):
    path = require_ref(value)
    raw = path.read_bytes()
    if digest(raw) != value["sha256"] or len(raw) != value["bytes"]:
        raise ValueError("public read changed")
    return raw

def write_new(path, value):
    # Windows rename refuses an existing destination. Do not use os.replace,
    # or run this publisher on a platform whose rename permits replacement.
    if os.name != "nt":
        raise OSError("atomic no-clobber publisher requires Windows")
    path = canonical_path(str(path))
    parent = canonical_path(str(path.parent))
    if not parent.is_dir():
        raise ValueError("existing canonical publication directory required")
    if os.path.lexists(path):
        raise FileExistsError("public destination already exists")
    raw = json.dumps(value, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
    temporary = parent/("." + path.name + "." + uuid.uuid4().hex + ".pending")
    created = False
    try:
        with temporary.open("xb") as stream:
            created = True
            if stream.write(raw) != len(raw):
                raise OSError("short public JSON write")
            stream.flush()
            os.fsync(stream.fileno())
        if canonical_path(str(parent)) != parent or not parent.is_dir():
            raise ValueError("publication directory changed")
        # Same-directory publication after close; the OS, not the earlier
        # existence check, enforces no clobber if another writer wins.
        os.rename(temporary, path)
    except BaseException as error:
        if created:
            try:
                temporary.unlink(missing_ok=True)
            except OSError as cleanup_error:
                # Keep the original failure type and the cleanup failure.
                # Never remove the destination or another call's temporary.
                raise error from cleanup_error
        raise
    return public_ref(path)


